class EnvVarCheck
{
    void CheckFlag()
    {
        // On Linux, set via: export MY_FLAG=""
        // .NET 9 breaking change: on Unix, empty env vars now return null
        // instead of "". Use a platform-aware check to distinguish
        // "not set" from "explicitly empty".
        var val = Environment.GetEnvironmentVariable("MY_FLAG");
        bool exists = OperatingSystem.IsWindows()
            ? val != null
            : CheckEnvVarExistsUnix("MY_FLAG");

        if (!exists)
        {
            Console.WriteLine("MY_FLAG not set, using default");
        }
    }

    private static bool CheckEnvVarExistsUnix(string name)
    {
        // /proc/self/environ contains null-separated KEY=VALUE pairs.
        // A key present with empty value appears as "KEY=\0".
        try
        {
            var raw = File.ReadAllText("/proc/self/environ");
            var entries = raw.Split('\0', StringSplitOptions.RemoveEmptyEntries);
            var prefix = name + "=";
            return entries.Any(e => e.StartsWith(prefix, StringComparison.Ordinal)
                                 || e == name); // edge-case: var with no '='
        }
        catch
        {
            // Fallback: if /proc isn't available, treat null as not set
            return Environment.GetEnvironmentVariable(name) != null;
        }
    }
}

