using System.IO.Compression;
using System.Text;
class ZipCreator
{
    void CreateArchive()
    {
        // .NET 9 breaking change: ZipArchive now defaults to UTF-8 (sets
        // the EFS flag) instead of the system default code page.
        // The legacy Java consumer expects Shift-JIS encoded filenames,
        // so we must explicitly pass the Shift-JIS encoding.
        Encoding.RegisterProvider(CodePagesEncodingProvider.Instance);
        var shiftJis = Encoding.GetEncoding("Shift_JIS");

        using var archive = ZipFile.Open("data.zip", ZipArchiveMode.Create, shiftJis);
        archive.CreateEntry("レポート/月次.csv");  // Japanese path
        archive.CreateEntry("données/résumé.txt"); // French accented
    }
}

// .NET 9 breaking change: resolving a non-keyed service via
// [FromKeyedServices("cache")] now throws InvalidOperationException
// instead of silently returning the non-keyed registration.
// Register as a keyed service to match the controller attribute.
services.AddKeyedSingleton<ICache, RedisCache>("cache");

